using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private OrderService _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _sut = new OrderService();
    }

    [TestClass]
    public sealed class CreateOrder
    {
        private OrderService _sut = null!;

        [TestInitialize]
        public void Setup()
        {
            _sut = new OrderService();
        }

        [TestMethod]
        public void ReturnsOrder_WithCorrectCustomerId()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 9.99m, Quantity = 2 }
            };

            var order = _sut.CreateOrder("cust-1", items);

            Assert.AreEqual("cust-1", order.CustomerId);
        }

        [TestMethod]
        public void ReturnsOrder_WithCalculatedTotal()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 10.00m, Quantity = 3 },
                new() { ProductName = "Gadget", Price = 5.50m, Quantity = 2 }
            };

            var order = _sut.CreateOrder("cust-1", items);

            Assert.AreEqual(41.00m, order.Total);
        }

        [TestMethod]
        public void ReturnsOrder_WithGeneratedId()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 1.00m, Quantity = 1 }
            };

            var order = _sut.CreateOrder("cust-1", items);

            Assert.IsFalse(string.IsNullOrEmpty(order.Id));
        }

        [TestMethod]
        public void ReturnsOrder_WithUtcCreatedAt()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 1.00m, Quantity = 1 }
            };

            var before = DateTime.UtcNow;
            var order = _sut.CreateOrder("cust-1", items);
            var after = DateTime.UtcNow;

            Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
        }

        [TestMethod]
        public void ThrowsArgumentNullException_WhenCustomerIdIsNull()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 1.00m, Quantity = 1 }
            };

            Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder(null!, items));
        }

        [TestMethod]
        public void ThrowsArgumentNullException_WhenItemsIsNull()
        {
            Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder("cust-1", null!));
        }

        [TestMethod]
        public void ThrowsInvalidOperationException_WhenItemsIsEmpty()
        {
            Assert.ThrowsExactly<InvalidOperationException>(() => _sut.CreateOrder("cust-1", []));
        }
    }

    [TestClass]
    public sealed class GetOrder
    {
        private OrderService _sut = null!;

        [TestInitialize]
        public void Setup()
        {
            _sut = new OrderService();
        }

        [TestMethod]
        public void ReturnsOrder_WhenOrderExists()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 5.00m, Quantity = 1 }
            };
            var created = _sut.CreateOrder("cust-1", items);

            var result = _sut.GetOrder(created.Id);

            Assert.IsNotNull(result);
            Assert.AreEqual(created.Id, result.Id);
        }

        [TestMethod]
        public void ReturnsNull_WhenOrderDoesNotExist()
        {
            var result = _sut.GetOrder("nonexistent-id");

            Assert.IsNull(result);
        }
    }

    [TestClass]
    public sealed class GetOrdersByCustomer
    {
        private OrderService _sut = null!;

        [TestInitialize]
        public void Setup()
        {
            _sut = new OrderService();
        }

        [TestMethod]
        public void ReturnsAllOrders_ForGivenCustomer()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 1.00m, Quantity = 1 }
            };
            _sut.CreateOrder("cust-1", items);
            _sut.CreateOrder("cust-1", items);
            _sut.CreateOrder("cust-2", items);

            var results = _sut.GetOrdersByCustomer("cust-1");

            Assert.AreEqual(2, results.Count);
        }

        [TestMethod]
        public void ReturnsEmptyList_WhenCustomerHasNoOrders()
        {
            var results = _sut.GetOrdersByCustomer("cust-no-orders");

            Assert.AreEqual(0, results.Count);
        }
    }
}

